<!-- 海康安防平台设备列表 -->
<template>
  <div class="hkaf">
    <div class="serch">
      <el-button type="primary" @click="handleClickAdd" size="small"><i class="el-icon-plus"></i>&nbsp;&nbsp;新增</el-button>
    </div>
    <div class="table">
      <div class="jia_table">
        <el-table :data="tableData" height="95%" style="width: 100%" :header-cell-style="{ background: '#f9fbff',height:'48.5px',fontSize:'14px' }" row-key="id" :tree-props="{children: 'children_qdsj', hasChildren: 'hasChildren'}" :span-method="arraySpanMethod">
          <!-- <el-table-column prop="Mine_id" label="Mine_id"></el-table-column> -->
          <el-table-column label="序号" type="index" :index="indexMethod"></el-table-column>
          <el-table-column prop="hik_name" label="安防平台区域名称"></el-table-column>
          <el-table-column prop="hik_host" label="安防平台地址"></el-table-column>
          <el-table-column prop="hik_port" label="端口"></el-table-column>
          <el-table-column label="安防平台识别码" width="150">
            <template slot-scope="scope">
              <span v-if="!scope.row.showIce">{{ maskedValue(scope.row.hik_appKey) }}</span>
              <span v-else>{{ scope.row.hik_appKey }}</span>
              &nbsp;&nbsp;
              <i @click.prevent="handleUpdateAppKey(scope.row)" class="el-icon-view" style="font-size: 16px;cursor: pointer;"></i>
            </template>
          </el-table-column>
          <el-table-column label="安防平台密钥" width="260">
            <template slot-scope="scope">
              <span v-if="!scope.row.showSecret">{{ maskedValue(scope.row.hik_appSecret) }}</span>
              <span v-else>{{ scope.row.hik_appSecret }}</span>
              &nbsp;&nbsp;
              <i v-if="!scope.row.showSecret" @click.prevent="handleUpdateSecret(scope.row)" class="el-icon-view" style="font-size: 16px;cursor: pointer;"></i>
            </template>
          </el-table-column>
          <el-table-column prop="hik_artemis" label="安防平台节点"></el-table-column>
          <el-table-column prop="created_at" label="创建时间">
            <template slot-scope="scope">
              {{ formatDate(scope.row.created_at) }}
            </template>
          </el-table-column>
          <el-table-column prop="updated_at" label="更新时间">
            <template slot-scope="scope">
              {{ formatDate(scope.row.updated_at) }}
            </template>
          </el-table-column>
          <el-table-column label="操作">
            <template slot-scope="scope">
              <el-button type="text" icon="el-icon-edit" size="small" @click="openEditDialog(scope.row)">详情</el-button>
            </template>
          </el-table-column>
        </el-table>
        <!-- 如果没有数据，显示空状态 -->
        <el-empty v-if="tableData.length === 0" image="/static/img/home/placeholder_kong.png" :image-size="307" description="暂时没有数据~"></el-empty>
      </div>
      <div class="jia_page">
        <el-pagination v-show="total > 0" :total="total" :page.sync="pageNum" :limit.sync="pageSize" @pagination="getData" layout="total, prev, pager, next, jumper,sizes" />
      </div>
    </div>
    <!-- 详情弹窗 -->
    <el-dialog title="详情信息" :visible.sync="detailOpen" width="80%">
      <el-descriptions title="设备类型">
        <el-descriptions-item label="设备名称">
          {{ detailForm.name }}
        </el-descriptions-item>
        <el-descriptions-item label="设备编码">
          {{ detailForm.indexCode }}
        </el-descriptions-item>
        <el-descriptions-item label="创建时间">
          {{ detailForm.created_at }}
        </el-descriptions-item>
        <el-descriptions-item label="更新时间">
          {{ detailForm.updated_at }}
        </el-descriptions-item>
      </el-descriptions>
      <el-descriptions title="通道信息" class="jia_description">
        <el-descriptions-item>
          <div style="width: 100%">
            <el-table :data="detailTable" height="390px" style="width: 100%">
              <el-table-column label="序号" type="index" width="80" />
              <el-table-column prop="manufacturer_type" label="厂商类型"></el-table-column>
              <el-table-column prop="equipment_ip" label="IP地址"></el-table-column>
              <el-table-column prop="equipment_type" label="设备类型"></el-table-column>
              <el-table-column prop="equipment_name" label="设备名称"></el-table-column>
              <el-table-column prop="Hik_indexCode" label="监控点编码"></el-table-column>
              <el-table-column prop="Hik_rtsp_url" label="视频流" :show-overflow-tooltip="true"></el-table-column>
            </el-table>
          </div>
          <br />
        </el-descriptions-item>
      </el-descriptions>
      <div class="jia_page">
        <el-pagination v-show="detailTotal > 0" @current-change="handleChangeDetail" @size-change="handleChangeDetail" :current-page.sync="detailpage" :page-size.sync="detailper_page" layout="total, sizes, prev, pager, next, jumper" :total="detailTotal">
        </el-pagination>
      </div>
    </el-dialog>
    <!-- 新增弹出框 -->
    <el-dialog title="新增配置" :visible.sync="dialogVisible" width="500px" @close="resetForm">
      <!-- 表单 -->
      <el-form :model="formData" :rules="rules" ref="form" label-position="top" status-icon class="demo-addUpdateForm">
        <el-form-item label="安防平台IP" prop="hik_host">
          <el-input v-model="formData.hik_host" placeholder="请输入安防平台IP"></el-input>
        </el-form-item>
        <el-form-item label="安防平台端口" prop="hik_port">
          <el-input v-model="formData.hik_port" placeholder="请输入安防平台端口"></el-input>
        </el-form-item>
        <el-form-item label="安防平台AppKey" prop="hik_appKey">
          <el-input v-model="formData.hik_appKey" placeholder="请输入安防平台AppKey"></el-input>
        </el-form-item>
        <el-form-item label="安防平台AppSecret" prop="hik_appSecret">
          <el-input v-model="formData.hik_appSecret" placeholder="请输入安防平台AppSecret"></el-input>
        </el-form-item>
        <el-form-item label="单位" prop="Mine_id">
          <el-select v-model="formData.Mine_id" placeholder="请选择单位">
            <el-option v-for="dict in Mine_id_type" :key="dict.id" :label="dict.mine_name" :value="dict.id"></el-option>
          </el-select>
        </el-form-item>
      </el-form>

      <!-- 操作按钮 -->
      <div slot="footer" class="dialog-footer">
        <el-button @click="dialogVisible = false">取消</el-button>
        <el-button type="primary" @click="submitForm">确认</el-button>
      </div>
    </el-dialog>
  </div>
</template>
  
  <script>
import { hkafApi } from "../../../api/hkaf/index"
export default {
  data() {
    return {
      tableData: [
        // {
        //   "Mine_id": 1,
        //   "created_at": "Wed, 04 Dec 2024 13:54:08 GMT",
        //   "hik_appKey": "",
        //   "hik_appSecret": "",
        //   "hik_artemis": "artemis",
        //   "hik_host": "https://192.168.139.246",
        //   "hik_methon": "POST",
        //   "hik_name": "白芦视频监控系统",
        //   "hik_port": "443",
        //   "updated_at": "Wed, 04 Dec 2024 13:54:08 GMT"
        // }
      ],
      total: 0,
      pageNum: 1,
      pageSize: 10,
      detailOpen: false,//详情弹窗开关
      detailForm: {},//详情数据
      detailTable: [],//详情弹窗监控点表格
      detailpage: 1,
      detailper_page: 10,
      detailTotal: 0,
      detailId: null,//用于标识当前详情弹窗的id信息
      // 新增
      dialogVisible: false, // 弹出框的显示状态
      formData: {
        hik_host: '',
        hik_port: '',
        hik_appKey: '',
        hik_appSecret: '',
        Mine_id: ''
      },
      // 表单校验规则
      rules: {
        hik_host: [
          { required: true, message: '请输入安防平台IP', trigger: 'blur' },
          {
            pattern: /^(?:(?:25[0-5]|2[0-4][0-9]|[01]?[0-9][0-9]?)\.){3}(?:25[0-5]|2[0-4][0-9]|[01]?[0-9][0-9]?)$/,
            message: '请输入有效的IPv4地址',
            trigger: ['blur','change']
          }
        ],
        hik_port: [
          { required: true, message: '请输入安防平台端口', trigger: 'blur' },
          { pattern: /^[0-9]+$/, message: '端口号必须为数字', trigger: 'blur' }
        ],
        hik_appKey: [
          { required: true, message: '请输入安防平台AppKey', trigger: 'blur' }
        ],
        hik_appSecret: [
          { required: true, message: '请输入安防平台AppSecret', trigger: 'blur' }
        ],
        Mine_id: [
          { required: true, message: '请选择单位', trigger: 'change' }
        ]
      },
      Mine_id_type: [],//单位字典
    };
  },
  created() {
    this.getData();
    this.getDictData();
  },
  mounted() {

  },
  methods: {
    arraySpanMethod({ row, column, rowIndex, columnIndex }) {
      // 获取数据量，以及需要屏蔽的行
      let res = this.tableData
      let num = this.tableData.length
      let arr = [], arrValue = 0
      for (let i = 0; i < num; i++) {
        arrValue = i
        arr.push(arrValue)
      }
      if (rowIndex !== 0) {  // 如果是偶数行
        // 合并第 1、2 列（索引 0 和 1）
        if (columnIndex === 1) {
          return [1, 2];  // 第1列和第2列跨1行，跨2列（合并第1列和第2列）
        }
        else if (columnIndex === 2) {
          return [0, 0]
        }
        else if (columnIndex === 4) {
          return [1, 3];  // 第5列（索引4）跨1行，跨3列（合并第5、6、7列）
        } else if (columnIndex === 5 || columnIndex === 6) {
          return [0, 0];  // 第6列和第7列不显示，依赖第5列合并
        }
        // else if (columnIndex === 3) {
        //   if (rowIndex === 1) {
        //     return [row.length - 1, 1];  // 第二行到最后一行合并
        //   }
        //   return [0, 0];  // 其他行不显示
        // }
      }
      return [1, 1];  // 默认每个单元格不合并，按正常显示
    },
    // 查询字典
    getDictData() {
      this.$http
        .get(this.$url.url_5000 + "/model_view/type_select", {
          params: {
            mine_id: '1',
            // id:''
          },
        })
        .then((response) => {
          if (response.data.code === 200) {
            this.Mine_id_type = response.data.mine_list
            this.formData.Mine_id = this.Mine_id_type[0].id
          }
        })
        .catch(function (response) {
          console.log(response);
        });
    },
    maskedValue(value) {
      if (value) {
        return value.replace(/./g, '*');
      }
    },
    indexMethod(index) {
      return (this.pageNum - 1) * this.pageSize + 1 + index;
    },
    // 处理表格中的注册时间、更新时间
    formatDate(inputTime) {
      // 解析输入的时间字符串
      const date = new Date(inputTime);

      // 获取年月日时分秒
      const year = date.getFullYear();
      const month = String(date.getMonth() + 1).padStart(2, '0'); // 月份从0开始，需要加1，并补零
      const day = String(date.getDate()).padStart(2, '0');
      const hours = String(date.getHours()).padStart(2, '0');
      const minutes = String(date.getMinutes()).padStart(2, '0');
      const seconds = String(date.getSeconds()).padStart(2, '0');

      // 组合格式化的日期时间字符串
      const formattedDate = `${year}-${month}-${day} ${hours}:${minutes}:${seconds}`;

      return formattedDate;
    },
    // 获取表格数据
    getData() {
      this.$http
        .get(hkafApi.getHkafList)
        .then((response) => {
          if (response.data.code === 200) {
            console.log(response.data.data.data);
            this.tableData = response.data.data.data.map(v => {
              let res = v.children_list
              let children_qdsj = res.map(k => {
                return {
                  id: k.id,
                  hik_appKey: k.indexCode,
                  hik_name: k.name,
                  created_at: k.created_at,
                  updated_at: k.updated_at,
                  hik_appSecret: null,
                  hik_artemis: null,
                  hik_host: null,
                  hik_methon: null,
                  Mine_id: null,
                  showIce: false,
                  showSecret: true,
                }
              })
              return {
                ...v,
                showIce: false,
                showSecret: false,
                children_qdsj
              }
            })
            console.log("tableData", this.tableData)
            this.total = response.data.data.length;
          }
        })
        .catch(function (response) {
          console.log(response);
        });
    },
    // 修改appKey显示状态
    handleUpdateAppKey(value) {
      // console.log(value)
      value.showIce = !value.showIce
    },
    // 修改secret的显示状态
    handleUpdateSecret(value) {
      // this.showSecret = !value
      value.showSecret = !value.showSecret
    },
    // mergeSiblings({ row, column, rowIndex, columnIndex }) {
    //   if (columnIndex === 5 || columnIndex === 6 || columnIndex === 7) {
    //     // 合并第三列和第四列
    //     return [1,2];
    //   }
    // },
    openEditDialog(row) {
      this.detailId = row.id
      this.$http.get(hkafApi.getHkafJkdList,
        {
          params: {
            page: this.detailpage,
            per_page: this.detailper_page,
            id: row.id,
          }
        }
      )
        .then(response => {
          this.detailForm = response.data.data
          this.detailTable = response.data.data.children
          this.detailTotal = response.data.data.total
          this.detailOpen = true
        })
        .catch(rek => {
          console.log(rek)
        })
    },
    handleChangeDetail() {
      this.$http.get(hkafApi.getHkafJkdList,
        {
          params: {
            page: this.detailpage,
            per_page: this.detailper_page,
            id: this.detailId,
          }
        }
      )
        .then(response => {
          this.detailForm = response.data.data
          this.detailTable = response.data.data.children
          this.detailTotal = response.data.data.total
        })
        .catch(rek => {
          console.log(rek)
        })
    },
    // 打开新增弹窗
    handleClickAdd() {
      this.dialogVisible = true
    },
    // 提交表单
    submitForm() {
      this.$refs.form.validate((valid) => {
        if (valid) {
          const loading = this.$loading({
            lock: true,
            text: "Loading",
            spinner: "el-icon-loading",
            background: "rgba(0, 0, 0, 0.7)",
          });
          // 在这里处理表单提交逻辑
          // console.log('提交数据:', this.formData);
          // this.dialogVisible = false; // 提交成功后关闭弹框
          const formData = new FormData();

          // 遍历 addUpdateForm 中的每个键值对，并添加到 formData 中
          Object.keys(this.formData).forEach(key => {
            formData.append(key, this.formData[key]);
          });
          let config = {
            headers: {
              "Content-Type": "multipart/form-data",
            },
          }
          this.$http.post(hkafApi.addHkafList, formData, config)
            .then(response => {
              this.$message({
                type: response.data.code == 200 ? 'success' : 'warning',
                message: response.data.msg,
              })
              loading.close();
            })
            .catch(rek => {
              console.log(rek)
              loading.close();
            })
        } else {
          console.log('表单验证失败!');
          loading.close();
          return false;
        }
      });
    },
    // 重置表单
    resetForm() {
      this.$refs.form.resetFields();
    }
  }
};
  </script>
  
  <style lang="scss" scoped>
.hkaf {
  width: 100%;
  height: 100%;
  background-color: #ffffff;
  border-radius: 6px;
  .serch {
    height: 70px;
    padding-top: 16px;
    padding-left: 25px;
    padding-bottom: 16px;
    box-sizing: border-box;
    position: relative;
    .demo-ruleForm {
      height: 70px;
      display: flex;
      justify-content: flex-start;
      align-items: flex-start;
      flex-wrap: wrap;
    }
  }
  .table {
    height: 87%;
    .jia_table {
      height: 100%;
      .el-table {
        height: 100%;
        background-image: url("../../../img/home/placeholder_bottom.png");
        background-position: bottom;
        background-size: 100% 60%;
        background-repeat: no-repeat;
      }
      ::v-deep .el-table--border .el-table__cell,
      .el-table__body-wrapper .el-table--border.is-scrolling-left ~ .el-table__fixed {
        border-right: none;
      }
      ::v-deep .el-table__empty-block {
        // display: none !important;
        .el-table__empty-text {
          color: transparent;
        }
      }
      ::v-deep .el-empty {
        width: 307px;
        height: 353px;
        position: absolute;
        top: 50%;
        left: 50%;
        margin-left: -153px;
        margin-top: -176px;
        .el-empty__image img {
          vertical-align: top;
          height: 147%;
          width: 100%;
        }
        .el-empty__description {
          margin-top: 20px;
          margin-right: 70px;
        }
      }
    }
    .jia_page {
      width: 100%;
      height: 33px;
      padding: 0 20px;
      // background-color: pink;
      text-align: right;
      position: absolute;
      right: 0;
      bottom: 21px;
    }
  }
  .jia_page {
    // width: auto;
    // height: 50px;
    // width: 100%;
    // height: 50px;
    // float: right;
    .el-pagination {
      height: 50px;
      white-space: nowrap;
      padding: 2px 5px;
      color: #303133;
      font-weight: 700;
      float: right;
    }
  }
  ::v-deep .demo-addUpdateForm {
    .el-select,
    .el-input {
      width: 100%;
      .el-input__inner {
        // width: 177px;
        height: 33px;
        background: #f7f6fb;
        border-radius: 4px;
        border: 1px solid #dcdfe6;
        box-sizing: border-box;
      }
      .el-input__suffix-inner {
        border-left: 1px solid #dcdfe6;
      }
    }
  }
  ::v-deep .demo-addUpdateForm {
    .el-form-item {
      margin-bottom: 0 !important;
    }
    .el-form-item__label {
      padding-bottom: 0;
    }
  }
  ::v-deep .jia_description {
    .el-descriptions-item__label.has-colon::after {
      content: "";
      // position: relative;
      // top: -0.5px;
    }
  }
}
</style>
  